/* global console, process */
import {readdir,stat} from "node:fs/promises";import path from "node:path";
const root=path.resolve("dist/assets");const files=await readdir(root);const sizes=await Promise.all(files.map(async(name)=>({name,bytes:(await stat(path.join(root,name))).size})));const kib=(value)=>value/1024;const initial=sizes.find((file)=>/^index-[\w-]+\.js$/.test(file.name));const errors=[];if(!initial)errors.push("No se encontró el chunk inicial.");else if(kib(initial.bytes)>500)errors.push(`El chunk inicial pesa ${kib(initial.bytes).toFixed(2)} KiB; máximo 500 KiB.`);for(const file of sizes.filter((item)=>item.name.endsWith(".js"))){if(kib(file.bytes)>500)errors.push(`${file.name} supera 500 KiB.`)}if(!sizes.some((file)=>file.name.startsWith("CompositionBuilderPage-")))errors.push("El constructor no quedó separado en un chunk diferido.");if(!sizes.some((file)=>file.name.startsWith("MediaAdminPage-")))errors.push("La biblioteca de medios no quedó separada.");if(errors.length){console.error(errors.join("\n"));process.exitCode=1}else console.log(`Presupuesto aprobado: inicial ${kib(initial.bytes).toFixed(2)} KiB; ${sizes.filter((v)=>v.name.endsWith(".js")).length} chunks JS.`);
